// Fonts offered for the emphasized headline word, signature, and badge
// text — each ships its own ideal weight since not every Google Font here
// has a 700 cut (some just re-render at their nearest). Cursive/script
// styles sit alongside a few clean, contemporary sans/display picks for
// agents who want the "Modern" layout (or any layout) to actually read as
// modern instead of defaulting to handwriting.
export const SCRIPT_FONTS = [
  { name: "Dancing Script", weight: 700, fallback: "cursive" },
  { name: "Pacifico", weight: 400, fallback: "cursive" },
  { name: "Great Vibes", weight: 400, fallback: "cursive" },
  { name: "Sacramento", weight: 400, fallback: "cursive" },
  { name: "Caveat", weight: 700, fallback: "cursive" },
  { name: "Parisienne", weight: 400, fallback: "cursive" },
  { name: "Poppins", weight: 800, fallback: "sans-serif" },
  { name: "Space Grotesk", weight: 700, fallback: "sans-serif" },
  { name: "Outfit", weight: 800, fallback: "sans-serif" },
  { name: "Bebas Neue", weight: 400, fallback: "sans-serif" },
];

export function scriptFontCss(name, sizePx) {
  const f = SCRIPT_FONTS.find((s) => s.name === name) || SCRIPT_FONTS[0];
  return `${f.weight} ${sizePx}px "${f.name}", ${f.fallback}`;
}

export function mixWithWhite(hex, amount) {
  const n = parseInt(hex.slice(1), 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  const mix = (c) => Math.round(c + (255 - c) * amount);
  return `rgb(${mix(r)}, ${mix(g)}, ${mix(b)})`;
}

export function drawCover(ctx, img, dx, dy, dW, dH, focusX = 0.5, focusY = 0.5, zoom = 1) {
  const imgRatio = img.width / img.height;
  const boxRatio = dW / dH;
  let baseSw, baseSh;
  if (imgRatio > boxRatio) {
    baseSh = img.height; baseSw = baseSh * boxRatio;
  } else {
    baseSw = img.width; baseSh = baseSw / boxRatio;
  }
  const z = Math.max(1, zoom);
  const sw = baseSw / z;
  const sh = baseSh / z;
  const sx = (img.width - sw) * focusX;
  const sy = (img.height - sh) * focusY;
  ctx.drawImage(img, sx, sy, sw, sh, dx, dy, dW, dH);
}

export function wrapText(ctx, text, maxWidth) {
  const words = text.split(" ");
  const lines = [];
  let line = "";
  for (const word of words) {
    const test = line ? line + " " + word : word;
    if (ctx.measureText(test).width > maxWidth && line) { lines.push(line); line = word; }
    else line = test;
  }
  if (line) lines.push(line);
  return lines;
}

export function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

export function archedRect(ctx, x, y, w, h) {
  const r = Math.min(w / 2, h * 0.55);
  ctx.beginPath();
  ctx.moveTo(x, y + h);
  ctx.lineTo(x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.lineTo(x + w - r, y);
  ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h);
  ctx.closePath();
}

// The brokerage's required contact strip — logo, agent name, phone/email,
// brokerage/city, office phone, and a headshot circle — drawn identically
// across every layout and every tool so the brand mark never gets dropped.
// showHeadshot lets a layout that already features the agent's photo
// elsewhere (e.g. a testimonial's reviewer photo) skip the redundant circle
// while still keeping the required logo/name/contact info.
export function drawContactBand(ctx, w, bandY, bandH, form, headshot, logo, showHeadshot = true) {
  const isDark = form.contactBg === "black";
  ctx.fillStyle = isDark ? BLACK : WHITE;
  ctx.fillRect(0, bandY, w, bandH);
  const contactTextColor = isDark ? WHITE : BLACK;

  const hasHeadshot = showHeadshot && !!headshot.img;
  const circleD = hasHeadshot ? bandH * 0.82 : 0;
  const circleCX = w - w * 0.03 - circleD / 2;
  const circleCY = bandY + bandH / 2;
  const headshotX = circleCX - circleD / 2;

  if (hasHeadshot) {
    ctx.save();
    ctx.beginPath();
    ctx.arc(circleCX, circleCY, circleD / 2, 0, Math.PI * 2);
    ctx.closePath();
    ctx.clip();
    const img = headshot.img;
    const shortSide = Math.min(img.width, img.height);
    const cropSize = shortSide * 0.82;
    const sx = (img.width - cropSize) / 2;
    ctx.drawImage(img, sx, 0, cropSize, cropSize, headshotX, circleCY - circleD / 2, circleD, circleD);
    ctx.restore();

    ctx.beginPath();
    ctx.arc(circleCX, circleCY, circleD / 2, 0, Math.PI * 2);
    ctx.strokeStyle = form.accentColor;
    ctx.lineWidth = Math.max(2, w * 0.004);
    ctx.stroke();
  }

  let textStartX = w * 0.045;
  if (logo.img) {
    const logoSize = bandH * 0.6;
    const logoY = bandY + (bandH - logoSize) / 2;
    const ratio = logo.img.width / logo.img.height;
    const logoW = logoSize * ratio;
    ctx.drawImage(logo.img, textStartX, logoY, logoW, logoSize);
    textStartX += logoW + w * 0.03;
  }

  const textMaxW = (hasHeadshot ? headshotX : w) - textStartX - w * 0.03;
  const mutedColor = isDark ? "rgba(255,255,255,0.6)" : UI.inkSoft;

  const fitFont = (text, weight, baseSize) => {
    let size = baseSize;
    ctx.font = `${weight} ${size}px "Montserrat", sans-serif`;
    const measured = ctx.measureText(text).width;
    if (measured > textMaxW) {
      size = size * (textMaxW / measured);
      ctx.font = `${weight} ${size}px "Montserrat", sans-serif`;
    }
    return size;
  };

  ctx.textAlign = "left";

  const nameSize = fitFont(form.agentName, 800, bandH * 0.175);
  const nameY = bandY + bandH * 0.32;
  ctx.fillStyle = contactTextColor;
  ctx.fillText(form.agentName, textStartX, nameY);

  ctx.strokeStyle = form.accentColor;
  ctx.lineWidth = Math.max(2, w * 0.0035);
  ctx.beginPath();
  ctx.moveTo(textStartX, nameY + bandH * 0.075);
  ctx.lineTo(textStartX + w * 0.055, nameY + bandH * 0.075);
  ctx.stroke();

  const contactY = bandY + bandH * 0.55;
  const contactSize = bandH * 0.11;
  const sep = "   •   ";
  if (form.agentPhone && form.agentEmail) {
    ctx.font = `600 ${contactSize}px "Montserrat", sans-serif`;
    let full = form.agentPhone + sep + form.agentEmail;
    let size = contactSize;
    let measured = ctx.measureText(full).width;
    if (measured > textMaxW) {
      size = size * (textMaxW / measured);
      ctx.font = `600 ${size}px "Montserrat", sans-serif`;
    }
    ctx.fillStyle = contactTextColor;
    ctx.fillText(form.agentPhone, textStartX, contactY);
    const phoneW = ctx.measureText(form.agentPhone).width;
    ctx.fillStyle = mutedColor;
    ctx.fillText(sep, textStartX + phoneW, contactY);
    const sepW = ctx.measureText(sep).width;
    ctx.fillStyle = form.accentColor;
    ctx.fillText(form.agentEmail, textStartX + phoneW + sepW, contactY);
  } else if (form.agentPhone || form.agentEmail) {
    ctx.fillStyle = form.agentPhone ? contactTextColor : form.accentColor;
    fitFont(form.agentPhone || form.agentEmail, 600, contactSize);
    ctx.fillText(form.agentPhone || form.agentEmail, textStartX, contactY);
  }

  const brokerLine = [form.brokerageName, form.brokerageCity].filter(Boolean).join("   ·   ");
  if (brokerLine) {
    fitFont(brokerLine, 700, bandH * 0.115);
    ctx.fillStyle = contactTextColor;
    ctx.fillText(brokerLine, textStartX, bandY + bandH * 0.76);
  }

  const officeParts = [];
  if (form.officePhone) officeParts.push(`Office  ${form.officePhone}`);
  if (form.website) officeParts.push(form.website);
  const officeLine = officeParts.join("   ·   ");
  if (officeLine) {
    fitFont(officeLine, 500, bandH * 0.09);
    ctx.fillStyle = mutedColor;
    ctx.fillText(officeLine, textStartX, bandY + bandH * 0.9);
  }
}

export function useUploadedImage() {
  const [img, setImg] = useState(null);
  const [name, setName] = useState("");
  const [focus, setFocus] = useState({ x: 0.5, y: 0.5 });
  const [zoom, setZoom] = useState(1);
  const load = (file) => {
    if (!file || !file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const image = new Image();
      image.onload = () => setImg(image);
      image.src = e.target.result;
    };
    setName(file.name);
    setFocus({ x: 0.5, y: 0.5 });
    setZoom(1);
    reader.readAsDataURL(file);
  };
  const clear = () => { setImg(null); setName(""); setFocus({ x: 0.5, y: 0.5 }); setZoom(1); };
  return { img, name, load, clear, focus, setFocus, zoom, setZoom };
}

// Loads a default hosted image (e.g. a standing headshot/logo) but still lets the
// agent swap in a different file any time — upload always takes priority over the
// default. If initialCustomUrl is given (e.g. loaded from a saved brand kit), that
// takes priority over the built-in default on first load.
export function useAgentAsset(defaultUrl, defaultLabel, initialCustomUrl) {
  const [img, setImg] = useState(null);
  const [source, setSource] = useState("loading"); // loading | default | custom | error
  const [name, setName] = useState(defaultLabel);
  const [url, setUrl] = useState(null); // raw data URL when source === "custom"

  useEffect(() => {
    if (initialCustomUrl) {
      const image = new Image();
      image.onload = () => { setImg(image); setSource("custom"); setUrl(initialCustomUrl); };
      image.onerror = () => setSource("error");
      image.src = initialCustomUrl;
      setName("Saved photo");
      return;
    }
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.onload = () => { setImg(image); setSource("default"); };
    image.onerror = () => setSource("error");
    image.src = defaultUrl;
  }, [defaultUrl, initialCustomUrl]);

  const load = (file) => {
    if (!file || !file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const image = new Image();
      image.onload = () => setImg(image);
      image.src = e.target.result;
      setUrl(e.target.result);
    };
    setName(file.name);
    setSource("custom");
    reader.readAsDataURL(file);
  };

  const clear = () => {
    setName(defaultLabel);
    setUrl(null);
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.onload = () => { setImg(image); setSource("default"); };
    image.onerror = () => setSource("error");
    image.src = defaultUrl;
  };

  return { img, name, source, url, load, clear };
}

// A plain background image with no upload UI of its own — used as a nicer
// empty-state backdrop than a flat color fill, for layouts where a photo
// is expected but hasn't been added yet.
export function useDefaultImage(url) {
  const [img, setImg] = useState(null);
  useEffect(() => {
    const image = new Image();
    image.onload = () => setImg(image);
    image.src = url;
  }, [url]);
  return img;
}

export function UploadBox({ label, icon: Icon, state, hint }) {
  const inputRef = useRef(null);
  const [dragOver, setDragOver] = useState(false);
  const isDefault = state.source === "default";
  return (
    <div>
      <span className="font-mono text-xs block mb-1.5" style={{ color: UI.inkSoft, letterSpacing: "0.04em" }}>{label}</span>
      <div
        onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
        onDragLeave={() => setDragOver(false)}
        onDrop={(e) => { e.preventDefault(); setDragOver(false); state.load(e.dataTransfer.files[0]); }}
        onClick={() => inputRef.current?.click()}
        className="rounded border-2 border-dashed flex items-center gap-2 cursor-pointer transition"
        style={{ borderColor: dragOver ? ACCENT : UI.line, background: UI.card, padding: "0.7rem 0.9rem" }}
      >
        <Icon size={16} style={{ color: ACCENT, flexShrink: 0 }} />
        {state.name ? (
          <div className="flex items-center gap-2 font-body text-sm flex-1 min-w-0">
            <span className="truncate">{isDefault ? `${state.name} (default)` : state.name}</span>
            {!isDefault && state.source !== "loading" && (
              <button onClick={(e) => { e.stopPropagation(); state.clear(); }} style={{ color: UI.inkSoft, flexShrink: 0 }} title="Reset to default">
                <X size={13} />
              </button>
            )}
          </div>
        ) : (
          <span className="font-body text-xs" style={{ color: UI.inkSoft }}>{hint}</span>
        )}
        <input ref={inputRef} type="file" accept="image/*" className="hidden" onChange={(e) => state.load(e.target.files[0])} />
      </div>
      {state.source === "error" && (
        <p className="font-body text-xs mt-1" style={{ color: ERROR }}>
          Couldn't load the default image — upload one here instead.
        </p>
      )}
    </div>
  );
}

// Lets an agent drag/zoom their uploaded photo within a frame shaped like the
// selected output aspect, instead of being stuck with an automatic center
// crop. Drag position maps directly to CSS background-position, which uses
// the same (imgSize - boxSize) * fraction math as drawCover, so what's shown
// here lines up with the exported image.
export function PhotoReposition({ state, aspect }) {
  const boxRef = useRef(null);
  const draggingRef = useRef(false);

  if (!state.img) return null;

  const { w: aw, h: ah } = ASPECTS[aspect] || ASPECTS.square;
  const maxBoxW = 300, maxBoxH = 140;
  const boxW = aw / ah > maxBoxW / maxBoxH ? maxBoxW : maxBoxH * (aw / ah);
  const boxH = aw / ah > maxBoxW / maxBoxH ? maxBoxW * (ah / aw) : maxBoxH;

  const updateFocusFromPoint = (clientX, clientY) => {
    const rect = boxRef.current.getBoundingClientRect();
    state.setFocus({
      x: Math.min(1, Math.max(0, (clientX - rect.left) / rect.width)),
      y: Math.min(1, Math.max(0, (clientY - rect.top) / rect.height)),
    });
  };

  const onPointerDown = (e) => {
    draggingRef.current = true;
    e.currentTarget.setPointerCapture(e.pointerId);
    updateFocusFromPoint(e.clientX, e.clientY);
  };
  const onPointerMove = (e) => {
    if (!draggingRef.current) return;
    updateFocusFromPoint(e.clientX, e.clientY);
  };
  const onPointerUp = (e) => {
    draggingRef.current = false;
    try { e.currentTarget.releasePointerCapture(e.pointerId); } catch {}
  };

  const imgRatio = state.img.width / state.img.height;
  const boxRatio = aw / ah;
  const bgSize = imgRatio > boxRatio
    ? `${(imgRatio / boxRatio) * 100 * state.zoom}% ${100 * state.zoom}%`
    : `${100 * state.zoom}% ${(boxRatio / imgRatio) * 100 * state.zoom}%`;

  const isDefaultFraming = state.zoom === 1 && state.focus.x === 0.5 && state.focus.y === 0.5;

  return (
    <div className="mt-3">
      <div className="flex items-center justify-between mb-1.5">
        <span className="font-mono text-xs" style={{ color: UI.inkSoft, letterSpacing: "0.04em" }}>REPOSITION PHOTO</span>
        {!isDefaultFraming && (
          <button
            type="button"
            onClick={() => { state.setFocus({ x: 0.5, y: 0.5 }); state.setZoom(1); }}
            className="font-body text-xs underline"
            style={{ color: UI.inkSoft }}
          >
            Reset
          </button>
        )}
      </div>
      <div
        ref={boxRef}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        className="rounded-lg border overflow-hidden touch-none select-none"
        style={{
          borderColor: UI.line,
          width: boxW,
          height: boxH,
          margin: "0 auto",
          backgroundImage: `url(${state.img.src})`,
          backgroundRepeat: "no-repeat",
          backgroundSize: bgSize,
          backgroundPosition: `${state.focus.x * 100}% ${state.focus.y * 100}%`,
          cursor: "grab",
        }}
      />
      <div className="flex items-center gap-2 mt-2">
        <span className="font-body text-xs flex-shrink-0" style={{ color: UI.inkSoft }}>Zoom</span>
        <input
          type="range"
          min="1"
          max="2.5"
          step="0.05"
          value={state.zoom}
          onChange={(e) => state.setZoom(parseFloat(e.target.value))}
          className="flex-1"
        />
      </div>
    </div>
  );
}

